<aside class="panel payment-summary shop-summary"><h2><?=e(t('รายการสินค้า'))?></h2><div class="checkout-items"><?php foreach($items as $item): ?><article class="checkout-item"><?=product_image_html($item,'',true,'80px')?><div><h3><?=e(localized_name($item))?></h3><?php if(!empty($item['variant_id'])): ?><p><?=e(($item['variant_color']??'').' / '.($item['variant_size']??''))?></p><?php endif ?><p><?=e(t('จำนวน'))?> <?=$item['quantity']?> · <?=money($item['price'])?> <?=e(t('/ ชิ้น'))?></p><strong><?=money(cents($item['price'])*$item['quantity']/100)?></strong></div></article><?php endforeach ?></div><h2><?=e(t('สรุปยอดชำระ'))?></h2>
<dl class="checkout-totals"><?php foreach(['subtotal'=>'ยอดรวมสินค้า','product_discount'=>'ส่วนลดสินค้า','coupon_discount'=>'ส่วนลดคูปอง','shipping_base'=>'ค่าจัดส่ง','shipping_discount'=>'ส่วนลดค่าจัดส่ง','cod_fee'=>'ค่าบริการ COD','net_before_tax'=>'มูลค่าก่อนภาษี','vat_amount'=>'ภาษีมูลค่าเพิ่ม','total'=>'ยอดสุทธิที่ต้องชำระ'] as $key=>$label): ?><div <?=$key==='cod_fee'?'data-cod-fee-row '.(($selectedMethod??'COD')!=='COD'?'hidden':''):''?> <?=in_array($key,['net_before_tax','vat_amount'],true)?'data-tax-block '.(empty($quote['tax_registered'])?'hidden':''):''?> class="<?=$key==='total'?'grand-total':''?>"><dt><?=e(t($label))?></dt><dd><?php if(str_contains($key,'discount')): ?>− <?php endif ?><span data-money="<?=$key?>"><?=money(($quote[$key]??($key==='subtotal'?$sum:0))/100)?></span></dd></div><?php endforeach ?></dl><ul data-applied-promotions><?php foreach($quote['applied']??[] as $promotion): ?><li><?=e($promotion['name'])?> − <?=money($promotion['discount']/100)?></li><?php endforeach ?></ul><p class="payment-help"><?=e(t('ยอดและสิทธิ์ส่วนลดตรวจอีกครั้งบนเซิร์ฟเวอร์ก่อนบันทึก หากเปลี่ยนระหว่างเปิดหน้า ระบบจะให้ทบทวนยอดใหม่'))?></p></aside>
